mapper.select:
SELECT chat_room_id, user_id, participant_role, participant_status,
       last_read_message_id, muted_yn, joined_at, left_at, created_at, updated_at
FROM chat_room_participant
WHERE chat_room_id = #{chatRoomId}
  AND user_id = #{userId}

mapper.update:
UPDATE chat_room_participant
SET participant_status = 'LEFT',
    left_at = CURRENT_TIMESTAMP
WHERE chat_room_id = #{chatRoomId}
  AND user_id = #{userId}
  AND participant_status = 'ACTIVE'
